package vn.covie.outbox.application; import org.springframework.stereotype.Service; import vn.covie.realtime.SseSignalPublisher; @Service public class OutboxProcessor {private final OutboxTransactionalProcessor transactions;private final OutboxFailureService failures;private final SseSignalPublisher sse;public OutboxProcessor(OutboxTransactionalProcessor t,OutboxFailureService f,SseSignalPublisher s){transactions=t;failures=f;sse=s;}public boolean processOne(){try{var result=transactions.processOneTransaction();if(!result.found())return false;sse.publish(result.signals());return true;}catch(OutboxProcessingException error){failures.recordFailure(error.eventId(),error.getCause());return true;}}}
